COLONIALISMO El colonialismo es un fenómeno histórico que abarca varios siglos y se caracteriza por la expansión y dominio de una potencia extranjera sobre territorios y poblaciones fuera de sus fronteras nacionales. Este proceso tuvo impactos profundos en las regiones colonizadas, dando forma a sus sociedades, economías y culturas de maneras complejas. Desde el siglo XV hasta mediados del siglo XX, el colonialismo se manifestó en diversas formas, desde la colonización directa hasta el establecimiento de imperios coloniales y la explotación económica de territorios lejanos. El inicio del colonialismo moderno se puede situar en los siglos XV y XVI, cuando las potencias europeas emprendieron expediciones marítimas en busca de rutas comerciales y recursos. El descubrimiento de América por Cristóbal Colón en 1492 y la posterior llegada de exploradores como Hernán Cortés y Francisco Pizarro marcaron el comienzo de la colonización en el continente americano. Estos exploradores buscaban rique.
