BOSSA NOVA\n\nESQUEMA GENERAL:\nMuy influenciada por las melodías y armonías del jazz, la bossa nova se toca como una samba "suave", con una sección rítmica simplificada y armonías más elaboradas.\n\nProcedente del sudeste de Brasil, concretamente de Río de Janeiro, la bossa nova alcanzó su apogeo a finales de los años 50 y es más conocida internacionalmente que la mayoría de las formas de música brasileña.\n\nAntonio Carlos Jobim (como compositor) y Joao Gilberto (principalmente como cantante y guitarrista) son los artistas más importantes de la bossa nova. Su primera grabación importante fue "Chega de Saudade" (marzo de 1959).
